---
name: browser
description: Use the installed OpenAI ChatGPT browser runtime through its node_repl MCP server
---

Use the plugin-provided `js` MCP tool for browser tasks. The MCP initialization instructions contain the exact verified browser-client URL for the installed ChatGPT.app. Import that URL before using `agent.browsers`.

For the standard `/Applications/ChatGPT.app` installation:

```js
if (globalThis.agent?.browsers == null) {
  const browserClient =
    await import("file:///Applications/ChatGPT.app/Contents/Resources/plugins/openai-bundled/plugins/chrome/scripts/browser-client.mjs");
  const runtime = await browserClient.setupBrowserRuntime({ globals: globalThis });
  if (runtime != null) globalThis.agent = runtime;
}
var availableBackends = await agent.browsers.list();
```

When the initialization instructions provide a different URL, use that exact URL instead.

Use OpenAI's browser abstractions rather than implementing CDP, navigation, screenshots, or file uploads yourself. Respect OpenAI's site and upload confirmations. Never bypass browser safety policy through raw CDP or alternative browser interfaces.

Do not print cookies, tokens, form values, private page content, or browser-profile data. Get explicit user approval immediately before an irreversible or externally visible action.

import assert from "node:assert/strict";
import { chmod, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";

import { registerClaudeMcp, removeClaudeMcpIfOwned } from "../dist/install/mcp.js";

async function withClaudeStub(stubBody, run) {
  const root = await mkdtemp(join(tmpdir(), "browserjack-mcp-"));
  const claudeStub = join(root, "claude-stub");
  const calls = join(root, "calls.log");
  await writeFile(
    claudeStub,
    `#!/bin/sh\nprintf '%s\\n' "$*" >> ${JSON.stringify(calls)}\n${stubBody}\n`,
  );
  await chmod(claudeStub, 0o755);

  const previous = process.env.CLAUDE_CLI_PATH;
  process.env.CLAUDE_CLI_PATH = claudeStub;
  try {
    await run({ calls });
  } finally {
    if (previous === undefined) {
      delete process.env.CLAUDE_CLI_PATH;
    } else {
      process.env.CLAUDE_CLI_PATH = previous;
    }
  }
}

test("refuses to overwrite a foreign MCP definition", async () => {
  await withClaudeStub(
    `if [ "$1 $2" = "mcp get" ]; then printf 'name:\\n  Command: /somewhere/else\\n  Args: run\\n'; exit 0; fi\nexit 0`,
    async () => {
      await assert.rejects(
        registerClaudeMcp("browserjack", "/opt/browserjack/bin/browserjack", "user", process.cwd()),
        /not owned by this installation/,
      );
    },
  );
});

test("keeps an already-owned MCP definition unchanged", async () => {
  await withClaudeStub(
    `if [ "$1 $2" = "mcp get" ]; then printf 'name:\\n  Command: /opt/browserjack/bin/browserjack\\n  Args: run\\n'; exit 0; fi\nexit 0`,
    async ({ calls }) => {
      const result = await registerClaudeMcp(
        "browserjack",
        "/opt/browserjack/bin/browserjack",
        "user",
        process.cwd(),
      );
      assert.equal(result, "unchanged");
      const recorded = await readFile(calls, "utf8");
      assert.doesNotMatch(recorded, /add-json/);
    },
  );
});

test("refuses to remove a foreign MCP definition", async () => {
  await withClaudeStub(
    `if [ "$1 $2" = "mcp get" ]; then printf 'name:\\n  Command: /somewhere/else\\n  Args: run\\n'; exit 0; fi\nexit 0`,
    async () => {
      await assert.rejects(
        removeClaudeMcpIfOwned(
          "browserjack",
          "/opt/browserjack/bin/browserjack",
          "user",
          process.cwd(),
        ),
        /Refusing to remove/,
      );
    },
  );
});

test("removes an owned MCP definition", async () => {
  await withClaudeStub(
    `if [ "$1 $2" = "mcp get" ]; then printf 'name:\\n  Command: /opt/browserjack/bin/browserjack\\n  Args: run\\n'; exit 0; fi\nexit 0`,
    async ({ calls }) => {
      const removed = await removeClaudeMcpIfOwned(
        "browserjack",
        "/opt/browserjack/bin/browserjack",
        "user",
        process.cwd(),
      );
      assert.equal(removed, true);
      const recorded = await readFile(calls, "utf8");
      assert.match(recorded, /mcp remove --scope user browserjack/);
    },
  );
});

test("reports nothing to remove when the server is absent", async () => {
  await withClaudeStub(`if [ "$1 $2" = "mcp get" ]; then exit 1; fi\nexit 0`, async () => {
    const removed = await removeClaudeMcpIfOwned(
      "browserjack",
      "/opt/browserjack/bin/browserjack",
      "user",
      process.cwd(),
    );
    assert.equal(removed, false);
  });
});

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { chmod, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";
import test from "node:test";

import { parse } from "yaml";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const workflow = parse(await readFile(join(root, ".github/workflows/release.yml"), "utf8"));
const sourceManifest = JSON.parse(await readFile(join(root, "package.json"), "utf8"));
const gate = workflow.jobs["release-gate"].steps.find((step) => step.id === "gate").run;
const mainOnly =
  "github.repository == 'stickerdaniel/browserjack' && (github.event_name == 'push' || github.event_name == 'workflow_dispatch') && github.ref == 'refs/heads/main'";
const setupNode = "actions/setup-node@820762786026740c76f36085b0efc47a31fe5020";
const downloadArtifact = "actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c";
const artifactName = "browserjack-${{ github.sha }}";

function normalized(value) {
  return value.replaceAll(/\s+/g, " ").trim();
}

function assertReleaseBoundary(value) {
  assert.deepEqual(Object.keys(value).toSorted(), ["jobs", "name", "on", "permissions"]);
  assert.deepEqual(value.permissions, { contents: "read" });
  assert.deepEqual(value.on.push, { branches: ["main"] });
  assert.ok(value.on.pull_request.paths.includes(".github/workflows/release.yml"));
  assert.ok(Object.hasOwn(value.on, "workflow_dispatch"));
  assert.deepEqual(Object.keys(value.on).toSorted(), ["pull_request", "push", "workflow_dispatch"]);

  const { verify, publish } = value.jobs;
  const releaseGate = value.jobs["release-gate"];
  assert.deepEqual(Object.keys(value.jobs).toSorted(), ["publish", "release-gate", "verify"]);
  assert.deepEqual(verify.permissions, { contents: "read" });
  assert.equal(verify.concurrency, undefined);
  assert.equal(verify.steps[0].with["persist-credentials"], false);
  assert.equal(verify.steps[1].with["node-version"], "24.21.0");
  assert.equal(verify.steps[1].with["package-manager-cache"], false);
  assert.equal(verify.steps[3].env.BROWSERJACK_RELEASE_GATE_TEST, "required");
  assert.equal(
    verify.steps[4].env.BROWSERJACK_ARTIFACT_DIR,
    "${{ runner.temp }}/browserjack-artifact",
  );
  assert.deepEqual(verify.steps[5].with, {
    name: artifactName,
    path: "${{ runner.temp }}/browserjack-artifact/*",
    "if-no-files-found": "error",
    "retention-days": 30,
  });

  assert.equal(releaseGate.needs, "verify");
  assert.equal(normalized(releaseGate.if), mainOnly);
  assert.deepEqual(releaseGate.permissions, { contents: "read" });
  assert.equal(releaseGate.concurrency, undefined);
  assert.equal(releaseGate.steps[0].with["persist-credentials"], false);
  assert.equal(releaseGate.steps[1].with["node-version"], "24.21.0");
  assert.deepEqual(releaseGate.steps[2].with, {
    name: artifactName,
    path: "${{ runner.temp }}/release",
  });
  assert.equal(releaseGate.steps[2].uses, downloadArtifact);
  assert.deepEqual(releaseGate.steps[3].env, { RELEASE_DIR: "${{ runner.temp }}/release" });
  assert.deepEqual(releaseGate.outputs, {
    publish: "${{ steps.gate.outputs.publish }}",
    version: "${{ steps.gate.outputs.version }}",
    sha256: "${{ steps.gate.outputs.sha256 }}",
  });

  assert.deepEqual(Object.keys(publish).toSorted(), [
    "concurrency",
    "environment",
    "if",
    "needs",
    "permissions",
    "runs-on",
    "steps",
    "timeout-minutes",
  ]);
  assert.deepEqual(publish.needs, ["verify", "release-gate"]);
  assert.equal(
    normalized(publish.if),
    `${mainOnly} && needs.release-gate.outputs.publish == 'true'`,
  );
  assert.deepEqual(publish.permissions, { "id-token": "write" });
  assert.deepEqual(publish.environment, {
    name: "npm",
    url: "https://www.npmjs.com/package/browserjack/v/${{ needs.release-gate.outputs.version }}",
  });
  assert.deepEqual(publish.concurrency, {
    group: "browserjack-npm-release",
    "cancel-in-progress": false,
  });
  assert.deepEqual(
    publish.steps.map((step) => step.uses ?? `run: ${step.name}`),
    [
      setupNode,
      "run: Require npm with trusted publishing support",
      downloadArtifact,
      "run: Publish the tested tarball",
    ],
  );
  assert.deepEqual(
    publish.steps.map((step) => Object.keys(step).toSorted()),
    [
      ["uses", "with"],
      ["name", "run"],
      ["uses", "with"],
      ["env", "name", "run"],
    ],
  );
  assert.deepEqual(publish.steps[0].with, {
    "node-version": "24.21.0",
    "registry-url": "https://registry.npmjs.org",
    "package-manager-cache": false,
  });
  assert.deepEqual(publish.steps[2].with, {
    name: artifactName,
    path: "${{ runner.temp }}/release",
  });
  assert.deepEqual(publish.steps[3].env, {
    RELEASE_DIR: "${{ runner.temp }}/release",
    VERSION: "${{ needs.release-gate.outputs.version }}",
    SHA256: "${{ needs.release-gate.outputs.sha256 }}",
  });
  assert.deepEqual(publish.steps[1].run.trim().split("\n"), [
    "set -euo pipefail",
    'npm_version="$(npm --version)"',
    "printf '11.5.1\\n%s\\n' \"$npm_version\" | sort -V -C || {",
    '  echo "::error::npm $npm_version is older than 11.5.1, which trusted publishing requires."',
    "  exit 1",
    "}",
  ]);
  assert.deepEqual(publish.steps[3].run.trim().split("\n"), [
    "set -euo pipefail",
    'tarball="$RELEASE_DIR/browserjack-$VERSION.tgz"',
    '[ "$(sha256sum "$tarball" | cut -d\' \' -f1)" = "$SHA256" ] || {',
    '  echo "::error::$tarball is not the tarball the release gate checked."',
    "  exit 1",
    "}",
    'npm publish "$tarball" --access public --ignore-scripts --registry https://registry.npmjs.org/',
    "{",
    '  echo "Published browserjack@$VERSION"',
    "  echo",
    '  echo "Tarball sha256: \\`$SHA256\\`"',
    '} >> "$GITHUB_STEP_SUMMARY"',
  ]);
  for (const [name, job] of Object.entries(value.jobs)) {
    if (name !== "publish") {
      assert.ok(!Object.hasOwn(job.permissions ?? {}, "id-token"));
      assert.ok(job.steps.every((step) => !/\bnpm\s+publish\b/.test(step.run ?? "")));
    }
    assert.ok(
      job.steps.every(
        (step) => step.shell === undefined && step["continue-on-error"] === undefined,
      ),
    );
  }
  assert.equal(JSON.stringify(value).includes("write-all"), false);
}

test("release workflow confines publishing credentials and the tested artifact", () => {
  assertReleaseBoundary(workflow);
});

test("release boundary rejects credential and artifact wiring changes", () => {
  for (const mutate of [
    (v) => {
      v.jobs.publish.steps[3].run = v.jobs.publish.steps[3].run.replace("--ignore-scripts", "");
    },
    (v) => {
      v.jobs.publish.steps[2].with.name = "another-artifact";
    },
    (v) => {
      v.jobs.publish.steps[3].env.SHA256 = "abc";
    },
    (v) => {
      v.jobs.verify.permissions["id-token"] = "write";
    },
    (v) => {
      v.jobs.verify.steps[3]["continue-on-error"] = true;
    },
    (v) => {
      v.jobs.publish.steps[3].shell = "node";
    },
    (v) => {
      v.jobs.publish.steps.unshift({ uses: "actions/checkout@main" });
    },
    (v) => {
      v.jobs.publish.if += " || true";
    },
    (v) => {
      v.on.push.tags = ["v*"];
    },
  ]) {
    const changed = structuredClone(workflow);
    mutate(changed);
    assert.throws(() => assertReleaseBoundary(changed));
  }
});

const npmBin = process.platform === "win32" ? "npm.cmd" : "npm";
const npmVersion = spawnSync(npmBin, ["--version"], { encoding: "utf8" });
const supportsGate = npmVersion.status === 0 && Number.parseInt(npmVersion.stdout, 10) >= 11;
if (!supportsGate && process.env.BROWSERJACK_RELEASE_GATE_TEST === "required") {
  test("release gate requires npm 11 when publishing is enabled", () => {
    assert.fail(
      `npm 11 is required for gate tests (got ${npmVersion.stdout.trim() || npmVersion.stderr.trim()})`,
    );
  });
}

const require = createRequire(import.meta.url);
const tar = supportsGate
  ? require(
      join(
        spawnSync(npmBin, ["root", "-g"], { encoding: "utf8" }).stdout.trim(),
        "npm/node_modules/tar",
      ),
    )
  : undefined;
const requiredEntries = [
  "package/package.json",
  "package/LICENSE",
  "package/dist/cli.js",
  "package/compatibility/manifest.json",
];

async function runGate({
  manifest = sourceManifest,
  members = requiredEntries,
  view = { status: 1, body: '{"error":{"code":"E404"}}' },
  checksum = true,
  archive,
} = {}) {
  const dir = await mkdtemp(join(tmpdir(), "browserjack-gate-"));
  try {
    const releaseDir = join(dir, "release");
    const stage = join(dir, "stage");
    const bin = join(dir, "bin");
    await mkdir(releaseDir);
    await mkdir(bin);
    for (const name of requiredEntries) {
      const path = join(stage, name);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(
        path,
        name === "package/package.json" ? JSON.stringify(manifest) : `${name}\n`,
      );
    }
    for (const name of members.filter((entry) => !requiredEntries.includes(entry))) {
      const path = join(stage, name);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, `${name}\n`);
    }
    await writeFile(join(dir, "package.json"), JSON.stringify(sourceManifest));
    const tarball = join(releaseDir, `browserjack-${sourceManifest.version}.tgz`);
    if (archive) {
      await writeFile(tarball, archive);
    } else {
      await tar.c({ file: tarball, gzip: true, cwd: stage, portable: true }, members);
    }
    const digest = createHash("sha256")
      .update(await readFile(tarball))
      .digest("hex");
    await writeFile(`${tarball}.sha256`, `${checksum ? digest : "0".repeat(64)}  ${tarball}\n`);
    const realNpm = spawnSync("/bin/sh", ["-c", "command -v npm"], {
      encoding: "utf8",
    }).stdout.trim();
    await writeFile(
      join(bin, "npm"),
      `#!/bin/sh\nif [ "$1" = view ]; then printf '%s\\n' "$NPM_VIEW_BODY"; exit "$NPM_VIEW_STATUS"; fi\nexec '${realNpm}' "$@"\n`,
    );
    await chmod(join(bin, "npm"), 0o755);
    const script = join(dir, "gate.sh");
    await writeFile(script, gate);
    const output = join(dir, "output");
    await writeFile(output, "");
    const result = spawnSync("/bin/bash", [script], {
      cwd: dir,
      env: {
        ...process.env,
        HOME: dir,
        PATH: `${bin}:${process.env.PATH}`,
        RELEASE_DIR: releaseDir,
        RUNNER_TEMP: dir,
        GITHUB_OUTPUT: output,
        NPM_VIEW_BODY: view.body,
        NPM_VIEW_STATUS: String(view.status),
      },
      encoding: "utf8",
      timeout: 30_000,
    });
    return { ...result, output: await readFile(output, "utf8"), digest };
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

const gateTest = supportsGate ? test : test.skip;
gateTest("release gate authorizes only an explicit npm E404", async () => {
  const absent = await runGate();
  assert.equal(absent.status, 0, absent.stdout + absent.stderr);
  assert.equal(
    absent.output,
    `publish=true\nversion=${sourceManifest.version}\nsha256=${absent.digest}\n`,
  );
  const present = await runGate({
    view: { status: 0, body: JSON.stringify(sourceManifest.version) },
  });
  assert.equal(present.status, 0, present.stdout + present.stderr);
  assert.match(present.output, /publish=false/);
  for (const view of [
    { status: 0, body: "" },
    { status: 0, body: "not json" },
    { status: 0, body: '"0.0.0"' },
    { status: 1, body: '{"error":{"code":"E500"}}' },
    { status: 1, body: "" },
  ]) {
    const result = await runGate({ view });
    assert.notEqual(result.status, 0, `view ${JSON.stringify(view)} was accepted`);
    assert.equal(result.output, "");
  }
});

gateTest("release gate rejects manifest, archive and hash mismatches", async () => {
  for (const args of [
    { manifest: { ...sourceManifest, name: "other" } },
    { manifest: { ...sourceManifest, version: "9.9.9" } },
    { manifest: { ...sourceManifest, publishConfig: { access: "public" } } },
    {
      manifest: {
        ...sourceManifest,
        publishConfig: { ...sourceManifest.publishConfig, registry: "https://example.test" },
      },
    },
    { members: [...requiredEntries, "shadow/package.json"] },
    { checksum: false },
  ]) {
    const result = await runGate(args);
    assert.notEqual(result.status, 0, JSON.stringify(args));
    assert.equal(result.output, "");
  }
});

function ustarArchive(members) {
  const blocks = members.flatMap(
    ({ name, data = "", type = "0", linkname = "", badChecksum = false }) => {
      const content = Buffer.from(data);
      const header = Buffer.alloc(512);
      const field = (value, start) => header.write(value, start, "latin1");
      const number = (value, start, length) =>
        field(`${value.toString(8).padStart(length - 1, "0")}\0`, start);
      field(name, 0);
      number(0o644, 100, 8);
      number(0, 108, 8);
      number(0, 116, 8);
      number(type === "0" ? content.length : 0, 124, 12);
      number(0, 136, 12);
      field(" ".repeat(8), 148);
      field(type, 156);
      field(linkname, 157);
      field("ustar\0", 257);
      field("00", 263);
      field(
        badChecksum
          ? "garbled!"
          : `${header
              .reduce((sum, byte) => sum + byte, 0)
              .toString(8)
              .padStart(6, "0")}\0 `,
        148,
      );
      if (type !== "0") return [header];
      const padded = Buffer.alloc(Math.ceil(content.length / 512) * 512);
      content.copy(padded);
      return [header, padded];
    },
  );
  return gzipSync(Buffer.concat([...blocks, Buffer.alloc(1024)]));
}

function packedMembers() {
  return requiredEntries.map((name) => ({
    name,
    data: name === "package/package.json" ? JSON.stringify(sourceManifest) : `${name}\n`,
  }));
}

gateTest("release gate rejects nonregular, duplicate and malformed entries", async () => {
  for (const members of [
    [...packedMembers(), { name: "package/dist/cli.js", data: "duplicate" }],
    [...packedMembers(), { name: "package/./extra", data: "dot path" }],
    [...packedMembers(), { name: "package/link", type: "2", linkname: "package.json" }],
    [{ name: "package/dist/notes", data: "bad", badChecksum: true }, ...packedMembers()],
  ]) {
    const result = await runGate({ archive: ustarArchive(members) });
    assert.notEqual(result.status, 0, JSON.stringify(members.map((m) => m.name)));
    assert.equal(result.output, "");
  }
});

{
  "mcpServers": {
    "browserjack": {
      "command": "${CLAUDE_PLUGIN_ROOT}/bin/browserjack-mcp"
    }
  }
}

import { assertCachedClientConsistent } from "../compat/manifest.js";
import { discoverRuntime } from "../discovery/app.js";
import { assertNativeHostsTrusted } from "../discovery/native-host.js";
import type { DiscoveredRuntime } from "../discovery/types.js";

export interface RuntimeLaunch {
  command: string;
  args: string[];
  env: NodeJS.ProcessEnv;
  runtime: DiscoveredRuntime;
}

function configPath(path: string): string {
  return JSON.stringify(path);
}

function permissionProfile(runtime: DiscoveredRuntime): string {
  const entries = [
    '"/"="read"',
    `${configPath(runtime.codexHome)}="write"`,
    '":tmpdir"="write"',
    '":slash_tmp"="write"',
  ];
  return `permissions.claude_browser_node_repl.filesystem={${entries.join(",")}}`;
}

// Node.js honours these to preload or inject arbitrary code. Never forward them
// into OpenAI's trusted runtime; a caller-set value would otherwise run inside
// the child outside NODE_REPL_TRUSTED_CODE_PATHS.
const DANGEROUS_ENV_VARS = [
  "NODE_OPTIONS",
  "NODE_REPL_EXTERNAL_MODULE",
  "NODE_REPL_EXTERNAL_MODULE_PATH",
] as const;

function sanitizedParentEnv(): NodeJS.ProcessEnv {
  const env = { ...process.env };
  for (const key of DANGEROUS_ENV_VARS) {
    delete env[key];
  }
  return env;
}

function runtimeEnv(runtime: DiscoveredRuntime): Record<string, string> {
  return {
    NODE_REPL_NODE_MODULE_DIRS: runtime.nodeModulesPath,
    NODE_REPL_NODE_PATH: runtime.nodePath,
    NODE_REPL_TRUSTED_CODE_PATHS: runtime.chromePluginPath,
    NODE_REPL_TRUSTED_BROWSER_CLIENT_SHA256S: runtime.browserClientSha256,
    // ChatGPT.app 26.814+ moved browser control into a trusted RPC service
    // that browser-client.mjs reaches through nodeRepl.rpc("browser", ...).
    ...(runtime.browserServicePath === undefined
      ? {}
      : { NODE_REPL_TRUSTED_SERVICES: JSON.stringify({ browser: runtime.browserServicePath }) }),
    BROWSER_USE_AVAILABLE_BACKENDS: process.env.BROWSER_USE_AVAILABLE_BACKENDS ?? "chrome",
    CODEX_HOME: runtime.codexHome,
    CODEX_CLI_PATH: runtime.codexPath,
  };
}

// JSON string escapes are valid TOML basic-string escapes, except that TOML
// also forbids a literal DEL.
function tomlString(value: string): string {
  return JSON.stringify(value).replaceAll("\u007f", "\\u007f");
}

// codex sandbox merges this override into shell_environment_policy from
// CODEX_HOME/config.toml, where ChatGPT.app writes its own NODE_REPL_* values.
// `set` wins over configured values and excludes; include_only runs after
// `set`, so it is cleared to keep a configured allowlist from dropping them.
function environmentPolicy(env: Record<string, string>): string {
  const entries = Object.entries(env).map(([key, value]) => `${key}=${tomlString(value)}`);
  return `shell_environment_policy={inherit="all",include_only=[],set={${entries.join(",")}}}`;
}

// Pure assembly of the sandbox invocation from an already-verified runtime.
// Kept side-effect free so the env and argument invariants stay testable
// without a real ChatGPT.app.
export function composeLaunch(runtime: DiscoveredRuntime): RuntimeLaunch {
  const env = runtimeEnv(runtime);
  return {
    command: runtime.codexPath,
    args: [
      "sandbox",
      "-c",
      permissionProfile(runtime),
      "-c",
      environmentPolicy(env),
      "-P",
      "claude_browser_node_repl",
      "-C",
      runtime.codexHome,
      "--allow-unix-socket",
      "/tmp/codex-browser-use",
      runtime.nodeReplPath,
      "--disable-sandbox",
    ],
    env: { ...sanitizedParentEnv(), ...env },
    runtime,
  };
}

// Every security check runs here, for every build: app and native-host
// signatures, cache byte-identity, containment. Build *compatibility* is
// established separately (manifest entry or one-time self-test); it gates
// nothing security-relevant.
export async function createRuntimeLaunch(appOverride?: string): Promise<RuntimeLaunch> {
  const runtime = await discoverRuntime(appOverride);
  assertCachedClientConsistent(runtime);
  await assertNativeHostsTrusted(runtime);
  return composeLaunch(runtime);
}

import type { Readable } from "node:stream";

export async function* readLines(input: Readable, maxLineBytes: number): AsyncGenerator<string> {
  let pending = Buffer.alloc(0);

  for await (const chunk of input) {
    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
    pending = Buffer.concat([pending, buffer]);

    for (;;) {
      const newline = pending.indexOf(0x0a);
      if (newline === -1) {
        break;
      }
      if (newline > maxLineBytes) {
        throw new Error(`MCP input line exceeds ${maxLineBytes} bytes`);
      }
      const line = pending.subarray(0, newline).toString("utf8");
      pending = pending.subarray(newline + 1);
      yield line.endsWith("\r") ? line.slice(0, -1) : line;
    }

    if (pending.length > maxLineBytes) {
      throw new Error(`MCP input line exceeds ${maxLineBytes} bytes`);
    }
  }

  if (pending.length > 0) {
    yield pending.toString("utf8");
  }
}

import { randomUUID } from "node:crypto";

import { isJsonObject, type JsonObject } from "../lib/json.js";

export interface TurnState {
  sessionId: string;
  turnCounter: number;
}

export function createTurnState(): TurnState {
  return {
    sessionId: `claude-browser-${randomUUID()}`,
    turnCounter: 0,
  };
}

export function injectTurnMetadata(line: string, state: TurnState): string {
  let value: unknown;
  try {
    value = JSON.parse(line) as unknown;
  } catch {
    return `${line}\n`;
  }

  if (!isJsonObject(value) || value.method !== "tools/call") {
    return `${line}\n`;
  }

  const params: JsonObject = isJsonObject(value.params) ? value.params : {};
  const metadata: JsonObject = isJsonObject(params._meta) ? params._meta : {};
  if ("x-codex-turn-metadata" in metadata) {
    return `${line}\n`;
  }

  state.turnCounter += 1;
  const turnMetadata = {
    installation_id: state.sessionId,
    session_id: state.sessionId,
    thread_id: state.sessionId,
    turn_id: `turn-${state.turnCounter}`,
    request_kind: "agent",
    turn_started_at_unix_ms: Date.now(),
  };

  return `${JSON.stringify({
    ...value,
    params: {
      ...params,
      _meta: {
        ...metadata,
        "x-codex-turn-metadata": turnMetadata,
      },
    },
  })}\n`;
}

import { Transform, type TransformCallback } from "node:stream";

const SECRET_KEY = "<REDACTED>";

const SECRET_PATTERNS: <REDACTED> [RegExp, string]> = [
  // JSON string form: "api_key":"value" -> keep structure, redact the value.
  [new RegExp(`("(?:${SECRET_KEY})"\\s*:\\s*")[^"]*(")`, "giu"), "$1[REDACTED]$2"],
  // authorization header form: redact the whole value to end of line (covers "Bearer <token>").
  [/(authorization\s*[:=]\s*)(?!")[^\n]+/giu, "$1[REDACTED]"],
  // key=value / key: value form (single unquoted token).
  [new RegExp(`((?:${SECRET_KEY})\\s*[:=]\\s*)(?!")[^\\s,;"']+`, "giu"), "$1[REDACTED]"],
  // Bearer tokens anywhere.
  [/(bearer\s+)[A-Za-z0-9._~+/=-]+/giu, "$1[REDACTED]"],
];

// Cap the buffered, not-yet-flushed line so a newline-free stderr stream cannot
// grow memory without bound. 64 KiB is far larger than any real diagnostic line.
const MAX_PENDING_BYTES = 64 * 1024;

function redactLine(value: string): string {
  return SECRET_PATTERNS.reduce((output, [pattern, replacement]) => {
    pattern.lastIndex = 0;
    return output.replace(pattern, replacement);
  }, value);
}

export class RedactingTransform extends Transform {
  #pending = "";

  override _transform(chunk: Buffer, _encoding: BufferEncoding, callback: TransformCallback): void {
    this.#pending += chunk.toString("utf8");
    const lines = this.#pending.split("\n");
    this.#pending = lines.pop() ?? "";
    for (const line of lines) {
      this.push(`${redactLine(line)}\n`);
    }
    if (Buffer.byteLength(this.#pending, "utf8") > MAX_PENDING_BYTES) {
      this.push(redactLine(this.#pending));
      this.#pending = "";
    }
    callback();
  }

  override _flush(callback: TransformCallback): void {
    if (this.#pending) {
      this.push(redactLine(this.#pending));
    }
    callback();
  }
}

